1	/**
2	 * Primitive identifier and envelope types shared by every Taskflow domain type.
3	 *
4	 * Every entity in Taskflow uses opaque branded string ids so that an `IssueId`
5	 * can never be silently passed where a `ProjectId` is expected. Ids are ULID
6	 * strings at runtime; the brand exists only at the type level.
7	 */
8	
9	declare const brand: unique symbol;
10	
11	/** Attaches a compile-time-only tag to a primitive type. */
12	export type Branded<T, B extends string> = T & { readonly [brand]: B };
13	
14	export type UserId = Branded<string, "UserId">;
15	export type OrgId = Branded<string, "OrgId">;
16	export type ProjectId = Branded<string, "ProjectId">;
17	export type IssueId = Branded<string, "IssueId">;
18	export type CommentId = Branded<string, "CommentId">;
19	export type MemberId = Branded<string, "MemberId">;
20	export type NotificationId = Branded<string, "NotificationId">;
21	export type ActivityId = Branded<string, "ActivityId">;
22	export type InvitationId = Branded<string, "InvitationId">;
23	export type LabelId = Branded<string, "LabelId">;
24	export type AttachmentId = Branded<string, "AttachmentId">;
25	export type SubscriptionId = Branded<string, "SubscriptionId">;
26	export type SessionId = Branded<string, "SessionId">;
27	export type WebhookId = Branded<string, "WebhookId">;
28	
29	/** Union of every branded id used in the app, for generic id helpers. */
30	export type AnyId =
31	  | UserId
32	  | OrgId
33	  | ProjectId
34	  | IssueId
35	  | CommentId
36	  | MemberId
37	  | NotificationId
38	  | ActivityId
39	  | InvitationId
40	  | LabelId
41	  | AttachmentId
42	  | SubscriptionId
43	  | SessionId
44	  | WebhookId;
45	
46	/** ISO-8601 timestamp string as stored in SQLite text columns. */
47	export type IsoTimestamp = Branded<string, "IsoTimestamp">;
48	
49	/** Rows carrying the standard created/updated bookkeeping columns. */
50	export interface Timestamps {
51	  readonly createdAt: IsoTimestamp;
52	  readonly updatedAt: IsoTimestamp;
53	}
54	
55	/**
56	 * Soft-delete marker. `archivedAt === null` means the row is live. Repositories
57	 * must filter on this via the helpers in `src/lib/soft-delete.ts` rather than
58	 * writing the predicate by hand.
59	 */
60	export interface SoftDeletable {
61	  readonly archivedAt: IsoTimestamp | null;
62	}
63	
64	/** Rows that belong to exactly one tenant. Enforced by `src/lib/tenant.ts`. */
65	export interface TenantScoped {
66	  readonly orgId: OrgId;
67	}
68	
69	export type SortDirection = "asc" | "desc";
70	
71	export interface SortSpec<TField extends string = string> {
72	  readonly field: TField;
73	  readonly direction: SortDirection;
74	}
75	
76	/** Cursor pagination request shared by every repository `list*` method. */
77	export interface PageRequest {
78	  readonly limit: number;
79	  readonly cursor?: string | null;
80	}
81	
82	/** Cursor pagination response shared by every repository `list*` method. */
83	export interface Page<T> {
84	  readonly items: readonly T[];
85	  readonly nextCursor: string | null;
86	  readonly total: number;
87	}
88	
89	/** Options accepted by every soft-delete-aware repository read. */
90	export interface ArchiveScope {
91	  readonly includeArchived?: boolean;
92	}
93	
94	export function makePage<T>(
95	  items: readonly T[],
96	  nextCursor: string | null,
97	  total: number,
98	): Page<T> {
99	  return { items, nextCursor, total };
100	}
101	
102	export function toIsoTimestamp(value: Date | string): IsoTimestamp {
103	  const date = typeof value === "string" ? new Date(value) : value;
104	  return date.toISOString() as IsoTimestamp;
105	}
