/**
 * Live, still-open issues whose due date has passed. Drives the overdue job.
 * An issue whose project is archived is never overdue, even when the issue
 * itself was left live by `archiveIssues: false`.
 */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select({ issue: issues })
    .from(issues)
    .innerJoin(
