import * as projectService from "@/server/services/project-service";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { subscribe } from "@/lib/event-bus";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("freeze");
});

afterAll(() => {
  cleanup();
});

describe("archived project freeze", () => {
  it("freezes issue writes when archiveIssues is false, lifts on restore", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Freezer",
      slug: "freezer",
      key: "FRZ",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const issue: Issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, project.id, { title: "Frozen issue" }),
    );

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "hello",
      parentId: null,
      mentionedUserIds: [],
    });

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });

    // Issue itself must still be live.
    const stillLive = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(stillLive.issue.archivedAt).toBeNull();

    await expect(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "renamed",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "in_progress",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "nope",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      commentService.updateComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "edited",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      commentService.deleteComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await expect(
      attachmentService.addAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        fileName: "a.png",
        sizeBytes: 100,
        contentType: "image/png",
        url: "https://example.com/a.png",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    // Reads keep working.
    const thread = await commentService.getThread(tenant.actors.member, tenant.org.id, issue.id);
    expect(thread.length).toBe(1);
    const board = await issueService.getBoard(tenant.actors.member, tenant.org.id, project.id);
    expect(board.flatMap((c) => c.issues).map((i) => i.id)).toContain(issue.id);

    // Restoring lifts the freeze.
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, project.id);
    const after = await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "renamed after restore",
    });
    expect(after.title).toBe("renamed after restore");
  });

  it("never announces an issue of an archived project as overdue, even after restore lifts it correctly", async () => {
    const project = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Overdue Freezer",
      slug: "overdue-freezer",
      key: "ODF",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const past = new Date(Date.now() - 1000 * 60 * 60 * 24).toISOString();
    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, project.id, { title: "Overdue frozen" }),
      dueAt: past as unknown as Issue["dueAt"],
    });

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: project.id,
      archiveIssues: false,
    });

    resetOverdueTracking();
    const seen: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      seen.push(payload.issueId);
    });

    await runOverdueIssueJob(new Date());
    off();

    expect(seen).not.toContain(issue.id);
  });
});

